SELECT COUNT(*) AS ipad_count
FROM nlq.listings
WHERE (title ILIKE '%ipad%' OR description ILIKE '%ipad%');

SELECT COUNT(*) AS brand_new_count
FROM nlq.listings
WHERE condition ILIKE '%brand new%';

SELECT COUNT(*) AS total_listings
FROM nlq.listings
WHERE meetup_spot ILIKE '%International Village%';

SELECT MAX(rent_price_per_week) AS highest_weekly_rent
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS board_game_count
FROM nlq.listings
WHERE category ILIKE '%board%';

SELECT ROUND(percentile_cont(0.5) WITHIN GROUP (ORDER BY l.rent_price_per_week)::numeric, 2) AS median_weekly_rent
FROM nlq.listings l
WHERE l.rent_price_per_week IS NOT NULL;

SELECT COUNT(*) AS pickup_only_count
FROM nlq.listings
WHERE meetup_spot ILIKE '%pickup only%';

SELECT COUNT(*) AS listings_since_oct_1
FROM nlq.listings
WHERE listed_at >= '2026-10-01'::date;

SELECT COUNT(*) AS review_count
FROM nlq.my_reviews
WHERE direction = 'given';

SELECT MAX(rating) AS worst_rating
FROM nlq.my_reviews
WHERE direction = 'received';

SELECT COUNT(*) AS removed_count
FROM nlq.my_listings
WHERE status = 'removed';

SELECT COUNT(DISTINCT category) AS distinct_categories
FROM nlq.my_deals
WHERE my_role = 'buyer' AND deal_type = 'sale' AND status = 'completed';

SELECT coalesce(sum(case when my_role = 'seller' then agreed_price else -agreed_price end), 0) AS net_gain
FROM nlq.my_deals
WHERE status = 'completed';

SELECT COUNT(*) AS total_requested_deals
FROM nlq.deals
WHERE status = 'requested';

SELECT ROUND(100.0 * COUNT(*) FILTER (WHERE status = 'cancelled') / COUNT(*), 2) AS cancelled_percent
FROM nlq.deals
WHERE deal_type = 'sale' AND status = 'cancelled';

SELECT COUNT(*) AS reserved_count
FROM nlq.listings_all
WHERE status = 'reserved';

SELECT COUNT(*) AS like_new_count
FROM nlq.listings_all
WHERE condition = 'like_new';

SELECT COUNT(*) AS suspended_accounts
FROM nlq.students
WHERE account_status = 'suspended';

SELECT COUNT(*) AS resolved_reports
FROM nlq.reports
WHERE status = 'resolved';

SELECT COUNT(*) AS listings_with_four_photos
FROM nlq.listings_all
WHERE photo_count = 4;

SELECT COUNT(*) AS total_1_star_reviews
FROM nlq.reviews
WHERE rating = 1;

SELECT COUNT(*) AS reports_against_listings
FROM nlq.reports
WHERE target_type = 'listing';

select count(*) as rented_out_items
from nlq.listings_all
where status = 'rented_out';

SELECT category, label
FROM nlq.categories
WHERE category_group = 'leisure';

SELECT round(avg(buyer_message_count)::numeric, 2) AS avg_buyer_messages,
       round(avg(seller_message_count)::numeric, 2) AS avg_seller_messages
FROM nlq.conversations;

SELECT COUNT(*) AS conversations_buyer_more_messages
FROM nlq.conversations
WHERE buyer_message_count > seller_message_count;

SELECT ROUND(100.0 * SUM(CASE WHEN rating = 5 THEN 1 ELSE 0 END) / COUNT(*), 2) AS percent_5_star_reviews
FROM nlq.reviews
WHERE reviewer_role = 'buyer';

SELECT COUNT(*) AS students_never_listed
FROM nlq.students s
WHERE NOT EXISTS (
    SELECT 1 FROM nlq.listings_all la
    WHERE la.seller_id = s.student_id
);

SELECT round(100.0 * COUNT(*) FILTER (WHERE resolved_at IS NOT NULL AND (resolved_at - filed_at) < INTERVAL '48 hours')::numeric / COUNT(*), 2) AS percent_within_48h
FROM nlq.reports
WHERE status = 'resolved';

SELECT ROUND(AVG(CASE WHEN r.rating >= 4.5 THEN 1 ELSE 0 END) * 100, 2) AS avg_4_5_plus_percent
FROM nlq.reviews r
WHERE r.reviewer_role = 'buyer';

select round(avg(extract(epoch from c.first_seller_reply_at - c.started_at) / 3600)::numeric, 2) as avg_reply_hours
from nlq.conversations c
where c.first_seller_reply_at is not null;
